/// <summary>
/// PricingAttribute of table <c>CustTable</c> field DefaultDirectDebitMandate.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Customer, GUPPricingAttributeSourceLevel::Header)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(CustTable, DefaultDirectDebitMandate))]
internal class GUPPricingAttributeCustTableDefaultDirectDebitMandate extends GUPPricingAttributeCustTable implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(CustTable, DefaultDirectDebitMandate);
}

public str getRefValue(Str _defaultValue)
{
    CustDirectDebitMandate custDirectDebitMandate;
    str ret = '';
    boolean isFirstAttributeToAppend = true;
    Query query = new Query();
    query.addDataSource(tableNum(CustDirectDebitMandate)).addRange(fieldNum(CustDirectDebitMandate, RecId)).value(_defaultValue);
    QueryRun qr = new QueryRun(query);
    while (qr.next())
    {
        custDirectDebitMandate = qr.get(tableNum(CustDirectDebitMandate), 1);
        if (!isFirstAttributeToAppend)
        {
            ret += ',';
        }
        else
        {
            isFirstAttributeToAppend = false;
        }
        ret += custDirectDebitMandate.MandateReference;
    }

    return ret;
}

public boolean validate(Str _defaultValue)
{
    var recId = str2Int64(_defaultValue);
    return CustDirectDebitMandate::find(recId) ? true : false;


}

public void lookupAllowedValues(object _formStringControl)
{
    GUPCustDirectDebitMandateLookup custDirectDebitMandateLookup = new GUPCustDirectDebitMandateLookup(true);
    custDirectDebitMandateLookup.performLookup(_formStringControl);

}
